/// Errors that may be returned by the TokenSwap program.
use anchor_lang::prelude::*;

#[error_code]
pub enum ErrorCode {
    #[msg("Not approved")]
    NotApproved,
    /// The owner of the input isn't set to the program address generated by the
    /// program.
    #[msg("Input account owner is not the program address")]
    InvalidOwner,
    /// The input token account is empty.
    #[msg("Input token account empty")]
    EmptySupply,
    /// The input token is invalid for swap.
    #[msg("InvalidInput")]
    InvalidInput,
    /// Address of the provided pool token mint is incorrect
    #[msg("Address of the provided lp token mint is incorrect")]
    IncorrectLpMint,
    /// Exceeds desired slippage limit
    #[msg("Exceeds desired slippage limit")]
    ExceededSlippage,
    /// Given pool token amount results in zero trading tokens
    #[msg("Given pool token amount results in zero trading tokens")]
    ZeroTradingTokens,
    #[msg("Not support token_2022 mint extension")]
    NotSupportMint,
    #[msg("invaild vault")]
    InvalidVault,
    #[msg("Init lp amount is too less(Because 100 amount lp will be locked)")]
    InitLpAmountTooLess,
    #[msg("TransferFee calculate not match")]
    TransferFeeCalculateNotMatch,
    #[msg("Math overflow")]
    MathOverflow,
    #[msg("Insufficient vault")]
    InsufficientVault,
    #[msg("Invalid fee model")]
    InvalidFeeModel,
    #[msg("Fee is zero")]
    NoFeeCollect,
    #[msg("Lamports calculate error")]
    LamportsCalculateError,
    /// DEEP: fund_fee_rate and fund_owner are fixed at build time (deep_keys::BUILDER;
    /// DEEP V1: the only rate is 0).
    #[msg("The builder fund fee (rate and owner) is fixed at build time")]
    BuilderFeeLocked,
    /// DEEP V1: protocol_owner is fixed at build time (deep_keys::FEE_VAULT).
    #[msg("The protocol fee owner is fixed at build time (the DEEP fee vault)")]
    ProtocolOwnerLocked,
    /// DEEP V1: a protocol fee recipient that is not the protocol owner's associated token
    /// account for that mint, or a protocol owner that is not the fee vault.
    #[msg("Protocol fees can only be collected to the DEEP fee vault's token accounts")]
    InvalidProtocolFeeRecipient,
    /// DEEP V1: trade + creator fee above the 10% hard cap (deep_keys::MAX_TOTAL_FEE_RATE).
    #[msg("Fee rates exceed the 10% hard cap")]
    FeeRateAboveCap,
    /// DEEP V1 (Phase 3): the pool and its AmmConfig are not of the same fee model, or the
    /// instruction / parameter does not exist for this config's fee model. A legacy pool is
    /// never priced with V1 rates and a V1 pool never with legacy rates.
    #[msg("Fee model mismatch between the pool, its AmmConfig or the instruction")]
    FeeModelMismatch,
    /// DEEP V1: reward_model must be 0 (Standard), 1 (Creator) or 2 (Holder).
    #[msg("Reward model must be 0 (Standard), 1 (Creator) or 2 (Holder)")]
    InvalidRewardModel,
    /// DEEP V1: a V1 pool takes its fees in ONE token, the quote: WSOL when the pair has it.
    #[msg("A V1 pool takes fees in its quote token only (WSOL when the pair has it)")]
    InvalidQuoteSide,
    /// DEEP V1: a pool's reward rate is 0 for Standard and at most `MAX_REWARD_RATE` (5%);
    /// an AmmConfig's current maximum is at most that ceiling too.
    #[msg("Reward rate must be 0 for Standard and at most 5% for Creator and Holder")]
    InvalidRewardRate,
    /// DEEP V1: `initialize_v1` opens a Holder pool only when the quote token is WSOL. SOL is
    /// always a reward asset of deep-rewards; any other token in a holder vault is paid to
    /// holders only if its distributor exists, which this program cannot check, so such a
    /// pool needs the permissioned `initialize_with_permission_v1`.
    #[msg("A permissionless Holder Rewards pool must be quoted in SOL")]
    HolderRewardsNeedSolQuote,
    /// DEEP V1: `initialize_v1` with a reward rate above the AmmConfig's current maximum
    /// (`max_reward_rate`, a rule for NEW pools only).
    #[msg("Reward rate is above the current maximum for new pools")]
    RewardRateAboveMax,
    /// DEEP (security review F2/F4): `create_pool_fee` above `deep_keys::MAX_CREATE_POOL_FEE`.
    #[msg("Create-pool fee exceeds the 0.15 SOL hard cap")]
    CreatePoolFeeAboveCap,
    /// DEEP (F2): the `Permission` of deep-curve's graduation payer can never be closed.
    #[msg("The graduation payer's permission cannot be closed")]
    GraduationPermissionLocked,
    /// DEEP (F4): a pool status can stop deposits and swaps, never withdrawals: an LP can
    /// always exit. Unknown status bits are rejected too.
    #[msg("Pool status can disable deposits and swaps only; withdrawals are always enabled")]
    InvalidPoolStatus,
    /// DEEP (F3): a Holder Rewards pool needs the deep-rewards distributor of (the non-quote
    /// token, the quote token) to exist already, passed as a remaining account: its reward
    /// fees are paid to the token's holder vault, where only that distributor moves them on.
    /// Exempt: a WSOL-quoted pool created with permission (graduation), whose WSOL can never
    /// be swept as stray and waits for the distributor.
    #[msg("A Holder Rewards pool needs its deep-rewards distributor to exist first")]
    HolderRewardsNeedDistributor,
}
